    """Return a closed chain using every domino, or None if none exists."""
    adjacency = {}
    stone_count = 0
    for stone_count, (left, right) in enumerate(dominoes, start=1):
        adjacency.setdefault(left, []).append((right, stone_count))
        adjacency.setdefault(right, []).append((left, stone_count))

    if not adjacency:
        return []
    if any(len(neighbors) % 2 for neighbors in adjacency.values()):
        return None

    # Hierholzer's algorithm: each physical stone is a distinct edge, even
    # when multiple stones have the same endpoints.
    used = set()
    stack = [next(iter(adjacency))]
    circuit = []
    while stack:
        neighbors = adjacency[stack[-1]]
        while neighbors and neighbors[-1][1] in used:
            neighbors.pop()
        if neighbors:
            neighbor, stone_id = neighbors.pop()
            used.add(stone_id)
            stack.append(neighbor)
        else:
            circuit.append(stack.pop())

    # Even degrees alone do not rule out disconnected groups of stones.
    if len(used) != stone_count:
        return None

    circuit.reverse()
    return list(zip(circuit, circuit[1:]))
