{"content":"import unittest
from collections import Counter

from dominoes import can_chain


class DominoesTest(unittest.TestCase):
    def assert_valid_chain(self, stones):
        original = list(stones)
        chain = can_chain(stones)
        self.assertIsNotNone(chain)
        self.assertEqual(len(chain), len(stones))
        self.assertEqual(
            Counter(tuple(sorted(stone)) for stone in chain),
            Counter(tuple(sorted(stone)) for stone in stones),
        )
        for index, stone in enumerate(chain):
            self.assertEqual(stone[1], chain[(index + 1) % len(chain)][0])
        self.assertEqual(stones, original)

    def test_empty_chain(self):
        self.assertEqual(can_chain([]), [])

    def test_single_stones(self):
        self.assert_valid_chain([(3, 3)])
        self.assertIsNone(can_chain([(1, 2)]))

    def test_reordering_and_reversing(self):
        self.assert_valid_chain([(2, 1), (2, 3), (1, 3)])

    def test_open_chain_is_impossible(self):
        self.assertIsNone(can_chain([(1, 2), (4, 1), (2, 3)]))

    def test_duplicate_stones_and_loops(self):
        self.assert_valid_chain([(1, 2), (1, 2), (1, 1), (2, 2)])
        self.assert_valid_chain([(1, 1), (1, 1)])

    def test_disconnected_even_degree_components(self):
        self.assertIsNone(can_chain([(1, 1), (2, 2)]))
        self.assertIsNone(can_chain([(1, 2), (2, 1), (3, 4), (4, 3)]))

    def test_joined_cycles(self):
        self.assert_valid_chain([
            (0, 1), (1, 2), (2, 0),
            (1, 3), (3, 4), (4, 1),
        ])

    def test_long_chain_without_recursion(self):
        self.assert_valid_chain([(i, i + 1) for i in range(2000)] + [(2000, 0)])


if __name__ == "__main__":
    unittest.main()
